python3 << 'EOF'
import json

with open('/Users/qiliangli/Documents/Coding/daily_news/technical-briefing-skill/workspace/runs/2026-08-08-200543/tasks/item_writing_batch/38eb371b97e38a4c6175fa37.output.json', 'r') as f:
    data = json.load(f)

def count_chars(s):
    return len(s)

limits = {
    'title': (4, 80),
    'core_conclusion': (25, 75),
    'mechanism': (18, 50),
    'result': (18, 50),
    'boundary': (10, 35),
    'project_relevance': (18, 50)
}

all_ok = True
for r in data['results']:
    eid = r['event_id'][:8]
    item = r['item']
    sub_total = sum(count_chars(item[f]) for f in ['core_conclusion', 'mechanism', 'result', 'boundary', 'project_relevance'])
    for field, (min_len, max_len) in limits.items():
        if field in item:
            length = count_chars(item[field])
            if not (min_len <= length <= max_len):
                print(f"{eid} {field}: {length} chars ({min_len}-{max_len}) FAIL")
                all_ok = False

if all_ok:
    print("ALL VALID")
    print(f"Event IDs: {[r['event_id'][:8]+'...' for r in data['results']]}")
    print(f"N items: {len(data['results'])}")
EOF
